begin
  perform pg_advisory_xact_lock(hashtextextended('sample-english-editor:spirit',0));
  select * into e from public.sample_english_editor_pages where page_key='spirit' for update;
  if not found or e.version<>(p->>'expectedVersion')::bigint or e.draft is distinct from p->'expectedDraft' or e.published is distinct from p->'expectedPublished' then
    raise exception 'English document changed; layout correction was not applied';
  end if;
  perform public.validate_site_editor_document(p->'draft');
  perform public.validate_site_editor_document(p->'published');
  stamp:=clock_timestamp();
  update public.sample_english_editor_pages set draft=p->'draft',published=p->'published',version=version+2,updated_at=stamp,published_at=stamp,updated_by=null where page_key='spirit';
  insert into public.sample_english_editor_revisions(page_key,document,published_at,published_by) values('spirit',p->'published',stamp,null);
end;
